PIE = "Piédrola Gil, Medicina Preventiva y Salud Pública, 12.ª ed. (2015)"
MAIS = "MINSA, Modelo de Atención Integral de Salud basado en Familia y Comunidad (MAIS-BFC), RM 464-2011/MINSA"
CAT = "MINSA, NTS 021-MINSA/DGSP-V.03, Categorías de establecimientos del sector salud (RM 546-2011/MINSA)"

Q(a="salud_publica", cat="Gestión", tema="MAIS-BFC: paquetes del Plan de Salud Local", año=2016, ext=False,
  e="En el Centro de Salud Ama Kella se está elaborando el Plan de Salud Local, requiriéndose la asistencia técnica (apoyo técnico, recursos y ejecución de proyectos). Según el MAIS basado en Familia y Comunidad, ¿en cuál de los paquetes está comprendida la asistencia técnica?",
  o=["Promoción de comunidades saludables.", "Producción de servicios.", "Metas de desarrollo sanitario local.", "Desarrollo institucional.", "Apoyo técnico de los servicios."], k="A",
  c="El Modelo de Atención Integral de Salud basado en Familia y Comunidad (MAIS-BFC), aprobado en 2011, organiza la oferta del primer nivel alrededor de la persona, la familia y la comunidad, con enfoque de territorio, de determinantes sociales y de promoción de la salud. Su instrumento de gestión local es el Plan de Salud Local, que se construye a partir del análisis de situación de salud y reúne las actividades en tres grandes paquetes: la producción de servicios, que agrupa la atención individual y familiar por etapas de vida; la promoción de comunidades saludables, que incluye la acción con gobiernos locales, agentes comunitarios, instituciones educativas y organizaciones sociales; y el desarrollo institucional, que cubre la gestión, la capacitación y la mejora de la calidad del propio establecimiento. En la formulación de la pregunta, la asistencia técnica y la ejecución de proyectos con otros actores del territorio se ubican en el paquete de promoción de comunidades saludables. La producción de servicios describe prestaciones directas, el desarrollo institucional se refiere al fortalecimiento interno, y las metas de desarrollo sanitario local y el apoyo técnico de los servicios no son paquetes del plan sino conceptos de apoyo. Perla clínica: ante preguntas de MAIS-BFC, recuerde la tríada producción, promoción y desarrollo institucional.",
  f=MAIS + "; " + PIE,
  nota="Clave A del libro. El enunciado es ambiguo porque la asistencia técnica interna también podría ubicarse en desarrollo institucional; se mantiene A. Las opciones C y E no corresponden a paquetes del plan.")

Q(a="salud_publica", cat="Planificación", tema="Definición de planificación en salud", año=2016, ext=False,
  e="Al proceso de valorización razonada de factores sociales, económicos, demográficos, políticos, sanitarios y otros, con el fin de tomar decisiones sobre la cantidad, calidad y tipo de recursos de salud para cubrir las demandas y problemas de salud en un período determinado, ¿cómo se le denomina?",
  o=["Planificación en salud.", "Análisis situacional.", "Planificación estratégica.", "Organización de sistemas de salud.", "Salud pública."], k="A",
  c="La planificación en salud es el proceso racional y dinámico mediante el cual se analiza una situación, se fijan objetivos, se estiman las necesidades de recursos y se eligen las actividades para alcanzarlos, de modo que la oferta de servicios responda a las demandas y problemas sanitarios de una población en un tiempo determinado. La definición del enunciado, centrada en la valoración razonada de factores sociales, económicos, demográficos, políticos y sanitarios para decidir cantidad, calidad y tipo de recursos, es la clásica de planificación sanitaria. Sus etapas son el diagnóstico o análisis de situación, la determinación de prioridades, la formulación de objetivos y metas, la programación de actividades, la ejecución y la evaluación. El análisis situacional (ASIS) es solo la primera etapa, de carácter descriptivo, y no implica asignar recursos. La planificación estratégica es una modalidad de la planificación, orientada a la misión, la visión y los objetivos de largo plazo de la institución. La organización de sistemas de salud trata de la estructura y las funciones de los componentes del sistema, y la salud pública es la disciplina más amplia que abarca estas acciones. Perla clínica: si el enunciado habla de decidir recursos según demandas y problemas, piense en planificación; si solo describe la situación, piense en ASIS.",
  f="OPS, Las funciones esenciales de la salud pública en las Américas: una renovación para el siglo XXI (2020); " + PIE)

Q(a="salud_publica", cat="Vigilancia", tema="Sala situacional y mapa epidemiológico de EDA", año=2016, ext=False,
  e="En un centro de salud se utiliza un mapa epidemiológico consignando el tipo de aprovisionamiento de agua en los hogares. Mensualmente se ubican en el mapa los casos de EDA, observándose la relación con hogares de suministro de agua inadecuado, lo cual facilita la planificación local para el control de la EDA. Esta información está disponible en:",
  o=["La sala situacional.", "Las estadísticas de gestión sanitaria.", "El avance de metas sanitarias.", "El monitoreo situacional.", "El monitoreo epidemiológico integral."], k="A",
  c="La sala situacional en salud es un espacio físico o virtual donde se reúnen, analizan y presentan de forma sistemática los datos de salud de un territorio para apoyar la toma de decisiones. Reúne mapas georreferenciados, gráficos de tendencia, tablas y alertas que muestran la distribución de los daños y de los factores condicionantes, como el acceso a agua segura, el saneamiento, la pobreza o la cobertura de servicios, y permite seguir mes a mes la evolución de los indicadores frente a las metas. En la situación descrita, el equipo ubica en un mapa los casos de enfermedad diarreica aguda y los cruza con el tipo de abastecimiento de agua de cada hogar, que es el ejemplo típico del análisis espacial que hace una sala situacional y que orienta la intervención local, por ejemplo la cloración, la vigilancia de la calidad del agua y la educación sanitaria. Las estadísticas de gestión sanitaria y el avance de metas miden la producción y el cumplimiento de objetivos programados, no relacionan factores de riesgo con casos. El monitoreo situacional y el monitoreo epidemiológico integral no son denominaciones de uso para este instrumento. Perla clínica: un mapa de riesgo con casos y determinantes superpuestos es la firma de la sala situacional.",
  f="OPS/OMS, Sala de situación de salud, conceptos y uso para la toma de decisiones; " + PIE,
  nota="La cita de OPS sobre sala de situación es un documento técnico de la serie de la OPS y no se verificó su año exacto, por lo que no se da. La clave A del libro se mantiene.")

Q(a="salud_publica", cat="Planificación", tema="Tipo de planificación en un establecimiento: operativa", año=2016, ext=False,
  e="El médico jefe de un establecimiento de salud realiza un taller con su equipo de gestión. Con base en el ASIS identifican y priorizan problemas, y programan tareas y recursos que garanticen la ejecución de actividades para el logro de objetivos y metas del siguiente año fiscal. ¿Qué tipo de planificación han desarrollado?",
  o=["Operativa.", "De recursos.", "Estratégica.", "Táctica.", "Contingencial."], k="A",
  c="Los niveles de planificación se distinguen por el horizonte temporal, el nivel de decisión y el grado de detalle. La planificación estratégica define misión, visión, valores y objetivos de largo plazo, por lo general de tres a cinco años o más, y la realiza la alta dirección. La táctica traduce esos objetivos a políticas y programas por áreas funcionales. La operativa convierte lo anterior en actividades, tareas, responsables, cronograma y recursos concretos para el corto plazo, habitualmente un año fiscal, y se plasma en el Plan Operativo Institucional, que se articula con el presupuesto. En el escenario, el equipo parte del análisis de situación de salud, prioriza problemas y programa tareas y recursos para el siguiente año fiscal: es planificación operativa. La planificación de recursos es un componente de cualquier plan y no un tipo con ese nombre, y la contingencial se prepara ante eventos adversos, como desastres, epidemias o falla de servicios básicos. La estratégica no se limita a un año ni asigna tareas diarias. Perla clínica: asocie operativa con año fiscal, actividades y metas, y estratégica con misión, visión y objetivos institucionales a mediano o largo plazo.",
  f=PIE + "; " + MAIS)

Q(a="salud_publica", cat="Gestión", tema="Cambio del perfil epidemiológico en un establecimiento I-4", año=2016, ext=False,
  e="En un establecimiento I-4, la evaluación de indicadores del último quinquenio muestra cambio de las primeras causas de morbilidad y de las prioridades sanitarias de la demanda, sin incremento de la población total. ¿Qué decisión estratégica debe tomar e implementar el equipo de gestión?",
  o=["Replantear la misión del establecimiento.", "Solicitar cambio del establecimiento a nivel II.", "Implementar servicio de hospitalización.", "Realizar mercadeo social para incremento de partos.", "Mejorar las técnicas de diagnóstico de laboratorio."], k="A",
  c="Un establecimiento I-4 es un centro de salud con internamiento del primer nivel de atención, con médicos de las cuatro especialidades básicas y unidades como consulta externa, patología clínica y farmacia, según la norma de categorías vigente. La categoría depende de la complejidad de los servicios y de la capacidad resolutiva, y se revisa por criterios técnicos, no por decisión local. En la pregunta cambió el perfil de morbilidad y de prioridades sanitarias, pero no creció la población, es decir, la demanda en volumen es estable y cambia su naturaleza. La decisión estratégica es revisar la razón de ser del establecimiento: replantear la misión y readecuar la cartera de servicios, la organización y los programas a las nuevas necesidades de la población, con base en el análisis de situación de salud. Solicitar ascenso a nivel II o abrir hospitalización supone una ampliación de oferta que no se justifica sin más población ni más complejidad. El mercadeo social para partos o mejorar el laboratorio son acciones tácticas aisladas que no responden al cambio de perfil. Perla clínica: cambia el perfil de demanda, cambia la misión y la cartera; crece la población, crece la oferta.",
  f=CAT + "; " + PIE,
  nota="Clave A del libro, de criterio de gestión; la cita de categorías se verificó solo en número y título.")

Q(a="salud_publica", cat="Medicamentos", tema="Información de medicamentos y uso racional", año=2016, ext=False,
  e="La información sobre productos farmacéuticos al personal de salud es un lineamiento orientado al logro de:",
  o=["Uso racional de productos farmacéuticos y farmacovigilancia.", "Acceso universal a productos farmacéuticos esenciales.", "Control sanitario de productos y establecimientos.", "Vigilancia sanitaria de productos y establecimientos farmacéuticos.", "Control publicitario de productos farmacéuticos."], k="A",
  c="La política nacional de medicamentos se estructura en lineamientos que se corresponden con objetivos: el acceso universal a medicamentos esenciales, la garantía de calidad, seguridad y eficacia mediante el control y la vigilancia sanitaria, y el uso racional. La Ley 29459 de 2009, ley de los productos farmacéuticos, dispositivos médicos y productos sanitarios, incorpora un capítulo sobre el uso racional, que encarga a la autoridad de salud promoverlo entre los profesionales y la comunidad, con prioridad a los medicamentos esenciales en denominación común internacional. Según la OMS, hay uso racional cuando los pacientes reciben los medicamentos adecuados a su necesidad clínica, en las dosis correspondientes a sus requerimientos, durante un período adecuado y al menor costo para ellos y su comunidad. Para lograrlo, el personal debe contar con información independiente y actualizada sobre indicaciones, interacciones y reacciones adversas, y notificar los eventos adversos, que es la base de la farmacovigilancia. El acceso universal es un objetivo de disponibilidad y de financiamiento; el control y la vigilancia sanitaria y el control publicitario son funciones regulatorias de la autoridad, que verifica establecimientos y propaganda y no consiste en informar al prescriptor. Perla clínica: información al prescriptor, uso racional y farmacovigilancia; inspección y publicidad, control sanitario.",
  f="Perú, Ley 29459, Ley de los productos farmacéuticos, dispositivos médicos y productos sanitarios (2009); " + PIE)

Q(a="salud_publica", cat="Demografía", tema="Indicador demográfico de estructura: razón de dependencia", año=2016, ext=False,
  e="¿Cuál de los siguientes es un indicador demográfico de la estructura poblacional?",
  o=["Densidad poblacional.", "Tasa global de fecundidad.", "Esperanza de vida al nacer.", "Razón de dependencia.", "Tasa de crecimiento anual de población."], k="D",
  c="La demografía estudia el tamaño, la composición y la dinámica de las poblaciones. Los indicadores estáticos describen una población en un momento dado, por ejemplo su tamaño, su distribución espacial (densidad poblacional) y su estructura por edad y sexo (pirámide poblacional, proporción de menores de 15 y mayores de 65 años, índice de envejecimiento, razón de masculinidad y razón de dependencia). Los indicadores dinámicos miden el cambio por nacimientos, muertes y migración: tasa bruta de natalidad, tasa global de fecundidad, esperanza de vida al nacer, mortalidad y tasa de crecimiento anual. La razón de dependencia relaciona la población potencialmente inactiva, es decir menores de 15 años (o 16) y mayores de 64, con la población en edad de trabajar, y por tanto resume la composición por edad: es el indicador de estructura de la pregunta. La densidad poblacional es un indicador de distribución espacial, y la fecundidad, la esperanza de vida y el crecimiento anual miden la evolución de la población. Perla clínica: en la transición demográfica, la pirámide pasa de base ancha a rectangular, la razón de dependencia infantil baja y la de envejecimiento sube, con mayor carga de enfermedades crónicas.",
  f=PIE,
  nota="Clave D del libro. Algunos textos agrupan la densidad como indicador de estructura espacial; la razón de dependencia es el único indicador de composición por edad entre las opciones.")

Q(a="salud_publica", cat="Determinantes", tema="Campos de la salud de Lalonde", año=2017, ext=False,
  e="¿Cuáles son los campos de la salud planteados por Marc Lalonde?",
  o=["Biología humana, medio ambiente, estilos de vida, organización de servicios de salud.", "Pobreza, violencia familiar, analfabetismo, carencia de servicios básicos.", "Acceso a los servicios de salud, educación, calidad de atención, medio ambiente.", "Contaminación del aire, agua, suelos, pobreza.", "Biología humana, medio ambiente, acceso a los servicios de salud, pobreza."], k="A",
  c="El informe Lalonde, «Una nueva perspectiva sobre la salud de los canadienses», publicado en 1974 por el entonces ministro de Salud y Bienestar de Canadá, fue el primer documento gubernamental en afirmar que el sistema de atención médica no era el principal responsable de la salud de la población. Propuso el concepto de campo de la salud, formado por cuatro elementos: la biología humana (genética, envejecimiento, aparatos y sistemas del organismo), el medio ambiente (físico, químico, biológico y social), el estilo de vida (tabaco, alcohol, alimentación, sedentarismo, conductas de riesgo) y la organización de la atención de salud (acceso, calidad y cobertura de los servicios). Se destacó que la mayor parte de la morbilidad y de la mortalidad prematura se asociaba al estilo de vida y al ambiente, mientras que la mayor parte del gasto se destinaba a los servicios. Este marco impulsó la promoción de la salud, y es el antecedente de la Carta de Ottawa de 1986 y de los modelos de determinantes sociales posteriores, como el de la Comisión de la OMS. Las demás opciones mezclan determinantes sociales o problemas ambientales concretos, o incluyen la pobreza, que no es uno de los cuatro campos. Perla clínica: los cuatro campos son biología, ambiente, estilo de vida y organización de servicios.",
  f="Lalonde M. A new perspective on the health of Canadians (Gobierno de Canadá, 1974); Marmot y cols., CSDH, Closing the gap in a generation (Lancet 2008;372:1661-9)")

Q(a="salud_publica", cat="Calidad", tema="Constancia de acreditación de establecimientos de salud", año=2017, ext=False,
  e="¿Cuál de las siguientes alternativas corresponde al documento emitido por la Comisión Nacional Sectorial o la Comisión Regional Sectorial, que da fe de que el establecimiento de salud cumple con el nivel predeterminado para brindar una atención en salud de calidad y haber aprobado la evaluación externa?",
  o=["Constancia de acreditación.", "Informe de evaluación externa.", "Informe técnico de la autoevaluación.", "Documento de categorización.", "Criterios de evaluación."], k="A",
  c="En el Perú, el funcionamiento de un establecimiento de salud se apoya en tres procesos diferentes. La habilitación verifica el cumplimiento de condiciones mínimas de infraestructura, equipamiento, personal y seguridad; la categorización lo ubica en un nivel de complejidad (I-1 a III-2) según su capacidad resolutiva y su cartera de servicios; la acreditación es un proceso voluntario de evaluación periódica de estándares de calidad, que busca que el usuario reciba una atención oportuna, segura, completa y con trato adecuado. Tiene dos fases: la autoevaluación, que realiza el propio establecimiento con el listado de estándares y que culmina en un informe técnico, y la evaluación externa, a cargo de evaluadores acreditados por la autoridad. Si el establecimiento alcanza el puntaje exigido, la Comisión Sectorial Nacional o la Regional emite la constancia de acreditación, que certifica el cumplimiento del nivel predeterminado de calidad. El informe de evaluación externa es un resultado intermedio que sustenta la decisión pero no la certifica. El informe de autoevaluación es previo, el documento de categorización pertenece a otro proceso y los criterios de evaluación son los estándares utilizados. Perla clínica: acreditación es calidad y voluntaria; habilitación y categorización son obligatorias.",
  f="MINSA, NTS 050-MINSA/DGSP-V.02, Norma técnica de salud para la acreditación de establecimientos de salud y servicios médicos de apoyo (RM 456-2007/MINSA); " + CAT,
  nota="La norma de acreditación puede haber sido actualizada con posterioridad; se cita la RM 456-2007/MINSA, cuyo número y año se verificaron. Clave A del libro; el comentario del libro marca B por error de edición.")

Q(a="salud_publica", cat="Sistemas de salud", tema="Redes integradas de servicios de salud y atención primaria", año=2017, ext=False,
  e="¿En qué contexto la OPS propone la implementación de las Redes Integradas de Servicios de Salud (RISS)?",
  o=["Atención primaria.", "Vigilancia en salud.", "Intersectorialidad.", "Determinantes sociales.", "Educación sanitaria."], k="A",
  c="Las Redes Integradas de Servicios de Salud (RISS) son redes de organizaciones que prestan, o hacen los arreglos para prestar, servicios equitativos e integrales a una población definida, y que rinden cuentas por sus resultados clínicos y económicos y por el estado de salud de esa población. La OPS las propuso en 2010 en el marco de la renovación de la atención primaria de salud en las Américas, porque los sistemas de la región estaban fragmentados, con duplicación de servicios, baja calidad técnica y poca satisfacción de los usuarios. La resolución del Consejo Directivo de 2009 las adoptó como estrategia para contribuir a los sistemas basados en atención primaria, más accesibles, equitativos y eficientes. Sus atributos incluyen una población y un territorio definidos, una amplia oferta de servicios, un primer nivel como puerta de entrada que coordina la atención, la gobernanza única y la participación social. La vigilancia en salud, la intersectorialidad, los determinantes sociales y la educación sanitaria son componentes o enfoques de la atención primaria renovada, no el contexto que da origen a las RISS. Perla clínica: RISS responde a la fragmentación, y el primer nivel es su pilar y coordinador.",
  f="OPS, Redes integradas de servicios de salud: conceptos, opciones de política y hoja de ruta para su implementación en las Américas (2010); " + MAIS,
  nota="Bloque dañado reconstruido con la imagen; las opciones se leyeron de la página y la clave A es la del libro.")

Q(a="salud_publica", cat="Determinantes", tema="Determinantes estructurales de la salud (CSDH)", año=2017, ext=False,
  e="En el marco conceptual de la Comisión sobre Determinantes Sociales de la Salud, ¿cuál de los siguientes corresponde a un determinante estructural?",
  o=["Educación.", "Acceso a los servicios de salud.", "Condiciones de vivienda.", "Cohesión social.", "Factores biológicos."], k="A",
  c="El marco conceptual de la Comisión de Determinantes Sociales de la Salud de la OMS (2008, desarrollado por Solar e Irwin en 2010) distingue dos grupos. Los determinantes estructurales son los que generan estratificación social y definen la posición socioeconómica de las personas en las jerarquías de poder, prestigio y acceso a recursos: el contexto socioeconómico y político (gobernanza, políticas macroeconómicas, sociales y de salud, cultura y valores) y la posición socioeconómica, que se mide por ingreso, educación, ocupación, clase social, género y raza o etnicidad. Estos determinantes operan sobre la exposición y la vulnerabilidad de cada grupo y generan las inequidades en salud. Los determinantes intermedios, en cambio, son las circunstancias materiales (vivienda, entorno físico, trabajo), los factores conductuales y biológicos, los factores psicosociales (como el estrés y la cohesión social) y el propio sistema de salud, y dependen de los estructurales. La educación es el ejemplo clásico de posición socioeconómica. El acceso a los servicios de salud, las condiciones de vivienda, la cohesión social y los factores biológicos son intermedios. Perla clínica: los determinantes estructurales son las causas de las causas, los intermedios son el camino por donde actúan.",
  f="Comisión sobre Determinantes Sociales de la Salud, OMS, Closing the gap in a generation (Lancet 2008;372:1661-9); Solar O, Irwin A. A conceptual framework for action on the social determinants of health (OMS, 2010)",
  nota="Bloque dañado reconstruido con la imagen: el libro lista Educación, Cohesión social, Gobernanza, Políticas y Factores biológicos, y marca A. Gobernanza y políticas también son estructurales (contexto socioeconómico y político), por lo que se reemplazaron por acceso a los servicios de salud y condiciones de vivienda, determinantes intermedios. Clave A sin cambio. La cita de Solar e Irwin (OMS, 2010) no se verificó en línea y se mantiene como referencia del marco.")

Q(a="salud_publica", cat="Funciones esenciales", tema="Funciones esenciales de la salud pública", año=2017, ext=False,
  e="¿Cuál de los siguientes aspectos corresponde a una de las funciones esenciales de la salud pública?",
  o=["Promover la responsabilidad social por la salud.", "Desarrollar la prevención secundaria.", "Desarrollo de los determinantes sociales de la salud.", "Promover el desarrollo de la infraestructura de salud.", "Desarrollar la atención hospitalaria especializada."], k="A",
  c="Las funciones esenciales de la salud pública (FESP) son el conjunto de capacidades que debe tener la autoridad sanitaria, en colaboración con la sociedad, para proteger y mejorar la salud de las poblaciones. La OPS las definió en 2002 con 11 funciones y las renovó en 2020, también con 11, incorporando la perspectiva de equidad, el enfoque de determinantes sociales, la participación social, la gobernanza y la preparación ante emergencias. El conjunto incluye el monitoreo y análisis de la situación, la vigilancia y el control de riesgos y daños, la promoción de la salud, la participación social, el desarrollo de políticas y capacidad de gestión, la regulación, la garantía de acceso y de calidad, el desarrollo de recursos humanos, la investigación y la reducción del impacto de emergencias. Son funciones de la autoridad y la sociedad, con responsabilidad social compartida, y no solo de los servicios asistenciales. La prevención secundaria, la infraestructura, la atención hospitalaria especializada y el desarrollo de determinantes no son FESP con ese enunciado, pues se refieren a niveles de prevención, recursos o atención clínica. Perla clínica: las FESP son capacidades del sistema, no programas clínicos.",
  f="OPS, Las funciones esenciales de la salud pública en las Américas: una renovación para el siglo XXI. Marco conceptual y descripción (2020); " + PIE,
  nota="Bloque dañado: la clave del libro es A. Se reemplazó la opción E original (promover la vigilancia en salud) porque la vigilancia en salud pública sí es una FESP reconocida y daba dos respuestas defendibles; se sustituyó por un distractor clínico. Se advierte que A no figura literalmente en el listado OPS y es una redacción del libro.")

Q(a="salud_publica", cat="Adulto mayor", tema="Categoría geriátrico complejo", año=2017, ext=False,
  e="Paciente de 85 años que cursa con insuficiencia cardiaca congestiva, hipertensión arterial no controlada y diabetes mellitus tipo 2 compensada, dependiente por demencia senil. Según la norma técnica de atención del adulto mayor, ¿cuál es la categoría que le corresponde?",
  o=["Geriátrico complejo.", "Adulto mayor frágil.", "Geriátrico frágil.", "Adulto mayor compensado.", "Geriátrico descompensado."], k="A",
  c="La norma técnica peruana de atención integral del adulto mayor de 2006 clasificaba a las personas de 60 años o más en cuatro categorías: activo saludable, enfermo, frágil y paciente geriátrico complejo. El adulto mayor frágil cumple dos o más de estas condiciones: edad de 80 años o más, dependencia parcial según el índice de Katz, deterioro cognitivo leve o moderado, manifestaciones depresivas, riesgo social, caídas recientes, pluripatología (tres o más enfermedades crónicas), enfermedad crónica incapacitante, polifarmacia, hospitalización en el último año o un índice de masa corporal fuera de rango. El paciente geriátrico complejo cumple tres o más de estas condiciones: edad de 80 años o más, pluripatología, proceso principal incapacitante con dependencia total en el índice de Katz, deterioro cognitivo severo, problema social grave o enfermedad terminal con pronóstico menor de seis meses. La paciente de 85 años tiene pluripatología (insuficiencia cardiaca, hipertensión, diabetes) y dependencia por demencia, que cumplen varios criterios, de modo que es geriátrica compleja. Las otras opciones no son categorías oficiales. Perla clínica: la valoración geriátrica integral con Katz, Pfeiffer y escala sociofamiliar permite clasificar y planificar el cuidado.",
  f="MINSA, NTS 207-MINSA/DGIESP-2023, Cuidado integral de salud de las personas adultas mayores (RM 789-2023/MINSA), que reemplazó a la NTS 043-MINSA/DGSP-V.01 (RM 529-2006/MINSA)",
  nota="El libro usa la NTS de 2006. La RM 789-2023/MINSA aprobó la NTS 207-2023 y derogó la anterior; no se verificó si la nueva norma conserva las mismas categorías, por lo que el comentario describe la clasificación de 2006. Clave A del libro sin cambio.")

Q(a="salud_publica", cat="Participación", tema="Comités de vigilancia ciudadana en salud", año=2017, ext=False,
  e="¿A través de qué mecanismo la vigilancia ciudadana contribuye a mejorar el diálogo, el entendimiento y el respeto entre los representantes de la población, del Estado y de la sociedad civil?",
  o=["Comités de vigilancia ciudadana en salud.", "Participación comunitaria.", "Empoderamiento social.", "Consejo municipal.", "Prefectura."], k="A",
  c="La participación ciudadana en salud es un derecho y un componente de la atención primaria y de las funciones esenciales de la salud pública. Se expresa en varios niveles, desde la información y la consulta hasta la decisión compartida y el control social. La vigilancia ciudadana es la forma organizada en que la población observa, evalúa y propone mejoras sobre los servicios y las políticas de salud, y busca la rendición de cuentas de las autoridades. En el Perú se canaliza a través de comités de vigilancia ciudadana en salud, formados por organizaciones de usuarios, asociaciones de pacientes y redes sociales, que de modo voluntario y sin remuneración reciben consultas, sugerencias y quejas, promueven buenos oficios y apoyan la promoción de la salud en los establecimientos, en favor de los usuarios. Facilitan el diálogo entre la población, el Estado y la sociedad civil. La participación comunitaria y el empoderamiento social son conceptos más amplios y no un mecanismo concreto. El consejo municipal es un órgano de gobierno local, y la prefectura es un órgano político del Ejecutivo sin función de vigilancia en salud. Perla clínica: vigilancia ciudadana significa control social con diálogo, no confrontación, y su producto son recomendaciones de mejora.",
  f="OPS, Las funciones esenciales de la salud pública en las Américas: una renovación para el siglo XXI (2020); " + PIE,
  nota="El libro cita la RM 422-2008/MINSA para el reconocimiento de estos comités; no se logró verificar en línea, por lo que no se cita. Clave A sin cambio.")

Q(a="salud_publica", cat="Planificación", tema="Definición de planificación en salud (repetida)", año=2017, ext=False,
  e="Al proceso que consiste en realizar una valorización razonada de una serie de factores sociales, económicos, demográficos, políticos, sanitarios, etc., con el fin de tomar decisiones sobre la cantidad, calidad y tipo de recursos de salud, con la finalidad de cubrir sus demandas y problemas de salud, en un momento o período determinado, ¿cómo se le denomina?",
  o=["Planificación en salud.", "Análisis situacional (ASIS).", "Planificación estratégica.", "Organización de sistemas de salud.", "Salud pública."], k="A",
  c="Esta pregunta repite el concepto de planificación en salud, que conviene estudiar desde su utilidad práctica. Planificar significa decidir hoy, con información, qué se hará mañana para cambiar una situación de salud. Un plan responde a cuatro interrogantes: dónde estamos, a dónde queremos llegar, cómo llegaremos y con qué recursos, y cómo sabremos que lo logramos. Por eso la planificación sanitaria articula la información demográfica, social, económica, política y epidemiológica con la capacidad de los servicios, y concluye en decisiones sobre cuántos recursos humanos, financieros y tecnológicos se necesitan, de qué calidad y de qué tipo. El ASIS aporta el diagnóstico inicial pero no decide recursos, y por eso no es la respuesta. La planificación estratégica es una de las metodologías para planificar, enfocada en misión, visión y objetivos de mediano y largo plazo, mientras que la operativa concreta actividades anuales. La organización de sistemas de salud describe cómo se estructuran y financian los servicios, y la salud pública es la disciplina y el conjunto de acciones colectivas por la salud de la población. Perla clínica: ante una definición larga que habla de valorar factores y decidir recursos, la respuesta es planificación, y ASIS se reserva para diagnóstico situacional.",
  f="OPS, Las funciones esenciales de la salud pública en las Américas: una renovación para el siglo XXI (2020); " + PIE,
  nota="Pregunta repetida de la de 2016 (bloque 1243), misma clave A; comentario redactado desde otro ángulo.")

Q(a="salud_publica", cat="Planificación", tema="Primer paso de la planificación: carga de enfermedad", año=2017, ext=False,
  e="¿Cuál es el primer paso del proceso de planificación en la medición del estado de salud global de la comunidad?",
  o=["La medición o evaluación de la carga de enfermedad.", "La determinación de las causas de enfermedad.", "La medición de la efectividad de las intervenciones.", "La implementación de las acciones.", "La monitorización o supervisión de las actividades."], k="A",
  c="El proceso de planificación sanitaria sigue una secuencia lógica: análisis de la situación, identificación y priorización de problemas, determinación de objetivos y metas, selección de estrategias e intervenciones, programación de actividades y recursos, ejecución, y monitoreo y evaluación. Antes de decidir qué hacer se necesita saber cuál es el estado de salud de la comunidad, y por eso el primer paso es medirlo mediante el análisis demográfico y socioeconómico, de morbilidad y mortalidad, y de la respuesta social. El estado de salud global se mide con indicadores de mortalidad general, específica, infantil, neonatal y materna, tasas de morbilidad por causa, edad y sexo, discapacidad y medidas sintéticas de carga de enfermedad como los años de vida ajustados por discapacidad (AVAD), que suman los años de vida perdidos por muerte prematura y los vividos con discapacidad. Solo después se estudian las causas de los problemas priorizados, se evalúa la efectividad de las posibles intervenciones, se implementan las acciones y se monitorean. Por eso las opciones B, C, D y E corresponden a pasos posteriores. Perla clínica: sin medir la carga de enfermedad no hay prioridades y sin prioridades no hay plan.",
  f="OPS, Las funciones esenciales de la salud pública en las Américas: una renovación para el siglo XXI (2020); " + PIE)

Q(a="salud_publica", cat="Gestión", tema="Gestión participativa y enfoque de sistema abierto", año=2017, ext=False,
  e="¿Cuál es el enfoque más recomendado para lograr una gestión participativa exitosa en los establecimientos de salud del primer nivel?",
  o=["De sistema abierto.", "De sistema cerrado.", "De subsistemas.", "Por objetivos.", "De contingencias."], k="A",
  c="La teoría general de sistemas aplicada a la administración considera que una organización es un conjunto de partes interrelacionadas que persiguen un fin común. Un sistema cerrado no intercambia información, energía o recursos con el entorno, y es un modelo teórico poco útil en salud. Un sistema abierto mantiene límites permeables, recibe insumos del ambiente (población, financiamiento, normas, tecnología), los transforma en servicios y recibe retroalimentación que corrige su desempeño. Un establecimiento del primer nivel es un sistema abierto porque su razón de ser es la comunidad de su territorio, con la que debe dialogar. La gestión participativa implica compartir información y decisiones con el equipo, las organizaciones comunitarias, los gobiernos locales y los usuarios, y exige ese intercambio dinámico permanente, que es lo que ofrece el enfoque de sistema abierto y lo que concuerda con el modelo de atención integral basado en la familia y la comunidad. La visión por subsistemas fragmenta el análisis en partes internas, la administración por objetivos se centra en metas y la teoría de contingencias adapta la estructura a circunstancias, pero ninguna garantiza por sí sola la apertura al entorno. Perla clínica: participación equivale a flujo de información en ambos sentidos entre servicio y comunidad.",
  f=MAIS + "; " + PIE)
